toad_implementation.code_blueprint:
canvas {
  size: 800px 960px;
  fill: #141414;
  font-family: "Anton, sans-serif";
}

>asphalt = #141414;
>actionOrange = #FF5500;
>boltYellow = #FFE600;
>white = #FFFFFF;

rect #speedStripe1 {
  at: center of canvas offset 0px -120px;
  size: 880px 24px;
  fill: >actionOrange;
  rotation: -12deg;
}

rect #speedStripe2 {
  at: below #speedStripe1 offset 8px;
  size: 880px 12px;
  fill: >boltYellow;
  rotation: -12deg;
}

text #actionHeroTitle {
  at: center of canvas offset 0px -60px;
  content: "D O W N H I L L";
  font-size: 84px;
  font-weight: 900;
  color: >white;
  rotation: -12deg;
}

text #actionHeroSub {
  at: below #actionHeroTitle offset 8px;
  content: "ALPINE EXTREME INVITATIONAL";
  font-size: 24px;
  font-weight: 900;
  color: >actionOrange;
  rotation: -12deg;
}

rect #locationBadge {
  at: bottom center of canvas offset 0px -60px;
  size: 480px 60px;
  fill: >boltYellow;
  rotation: -4deg;
}

text #badgeText {
  at: center of #locationBadge;
  content: "INNSBRUCK BIKE PARK • 05. OKTOBER 2026";
  font-size: 16px;
  font-weight: 800;
  color: #141414;
}
